/*
 * CyberWarrior recompiler runtime: CPU state, GBA memory map and ARM7TDMI flag semantics
 * used by the C generated by thumb2c.py.
 */
#ifndef CW_RT_H
#define CW_RT_H
#include <stdint.h>

typedef uint32_t u32;
typedef int32_t s32;
typedef uint16_t u16;
typedef uint8_t u8;
typedef uint64_t u64;
typedef int64_t s64;

typedef struct CwCpu {
    u32 r[16];
    u32 n, z, c, v;      /* flags, 0 or 1 */
    u32 ret;             /* address a function returned (or unwound) to */
    int fault;           /* set on an unmapped access / unsupported instruction */
    u32 fault_addr;
    u64 insns;           /* executed instruction count (approximate cycles later) */
} CwCpu;

/* ---- memory --------------------------------------------------------------------------- */
extern u8 cw_ewram[0x40000], cw_iwram[0x8000], cw_io[0x400], cw_pal[0x400], cw_vram[0x18000],
    cw_oam[0x400], cw_sram[0x10000];
extern const u8 *cw_rom;
extern u32 cw_rom_size;

u8 *cw_mem_ptr(CwCpu *c, u32 addr, u32 size, int write);   /* NULL + fault if unmapped */
void cw_io_write(CwCpu *c, u32 addr, u32 value, u32 size);  /* hook for hardware registers */

static inline u32 rd8(CwCpu *c, u32 a) { u8 *p = cw_mem_ptr(c, a, 1, 0); return p ? *p : 0; }
static inline u32 rd16raw(CwCpu *c, u32 a) { u8 *p = cw_mem_ptr(c, a & ~1u, 2, 0); return p ? (u32)(p[0] | p[1] << 8) : 0; }
static inline u32 rd32raw(CwCpu *c, u32 a) { u8 *p = cw_mem_ptr(c, a & ~3u, 4, 0); return p ? (u32)(p[0] | p[1] << 8 | p[2] << 16 | (u32)p[3] << 24) : 0; }
static inline u32 ror32(u32 v, u32 n) { n &= 31; return n ? (v >> n) | (v << (32 - n)) : v; }
/* ARM7TDMI: misaligned LDR/LDRH rotate the aligned value; LDRSH at an odd address = LDRSB.
 * cw_plain_unaligned (tests only) switches to plain byte-wise unaligned reads, like ARMv6+ /
 * the Unicorn reference, to tell ARM7 quirks apart from real recompiler differences. */
extern int cw_plain_unaligned;
static inline u32 rd8(CwCpu *c, u32 a);
static inline u32 rdbytes(CwCpu *c, u32 a, int n) { u32 v = 0; for (int i = 0; i < n; ++i) v |= rd8(c, a + i) << (8 * i); return v; }
static inline u32 rd32(CwCpu *c, u32 a) { if (cw_plain_unaligned && (a & 3)) return rdbytes(c, a, 4); return ror32(rd32raw(c, a), (a & 3) * 8); }
static inline u32 rd16(CwCpu *c, u32 a) { if (cw_plain_unaligned && (a & 1)) return rdbytes(c, a, 2); return ror32(rd16raw(c, a), (a & 1) * 8); }
static inline u32 rds8(CwCpu *c, u32 a) { return (u32)(s32)(int8_t)rd8(c, a); }
static inline u32 rds16(CwCpu *c, u32 a) {
    if (a & 1) return cw_plain_unaligned ? (u32)(s32)(int16_t)rdbytes(c, a, 2) : rds8(c, a);
    return (u32)(s32)(int16_t)rd16raw(c, a);
}
void wr8(CwCpu *c, u32 a, u32 v);
void wr16(CwCpu *c, u32 a, u32 v);
void wr32(CwCpu *c, u32 a, u32 v);

/* ---- flags ---------------------------------------------------------------------------- */
static inline u32 nz(CwCpu *c, u32 r) { c->n = r >> 31; c->z = r == 0; return r; }
static inline u32 add_f(CwCpu *c, u32 a, u32 b) {
    u32 r = a + b; c->c = r < a; c->v = ((~(a ^ b) & (a ^ r)) >> 31); return nz(c, r);
}
static inline u32 sub_f(CwCpu *c, u32 a, u32 b) {
    u32 r = a - b; c->c = a >= b; c->v = (((a ^ b) & (a ^ r)) >> 31); return nz(c, r);
}
static inline u32 adc_f(CwCpu *c, u32 a, u32 b) {
    u64 w = (u64)a + b + c->c; u32 r = (u32)w; c->c = (u32)(w >> 32); c->v = ((~(a ^ b) & (a ^ r)) >> 31); return nz(c, r);
}
static inline u32 sbc_f(CwCpu *c, u32 a, u32 b) {
    u32 borrow = !c->c; u32 r = a - b - borrow; c->c = (u64)a >= (u64)b + borrow;
    c->v = (((a ^ b) & (a ^ r)) >> 31); return nz(c, r);
}
/* shifts by immediate (format 1): amount 0 means LSL#0 / LSR#32 / ASR#32 */
static inline u32 lsl_i(CwCpu *c, u32 v, u32 n) { if (n) c->c = (v >> (32 - n)) & 1; return nz(c, n ? v << n : v); }
static inline u32 lsr_i(CwCpu *c, u32 v, u32 n) { if (!n) { c->c = v >> 31; return nz(c, 0); } c->c = (v >> (n - 1)) & 1; return nz(c, v >> n); }
static inline u32 asr_i(CwCpu *c, u32 v, u32 n) { if (!n) { c->c = v >> 31; return nz(c, (u32)((s32)v >> 31)); } c->c = (v >> (n - 1)) & 1; return nz(c, (u32)((s32)v >> n)); }
/* shifts by register (format 4): amount = Rs & 0xFF */
static inline u32 lsl_r(CwCpu *c, u32 v, u32 s) {
    s &= 0xFF; if (!s) return nz(c, v);
    if (s < 32) { c->c = (v >> (32 - s)) & 1; return nz(c, v << s); }
    c->c = s == 32 ? v & 1 : 0; return nz(c, 0);
}
static inline u32 lsr_r(CwCpu *c, u32 v, u32 s) {
    s &= 0xFF; if (!s) return nz(c, v);
    if (s < 32) { c->c = (v >> (s - 1)) & 1; return nz(c, v >> s); }
    c->c = s == 32 ? v >> 31 : 0; return nz(c, 0);
}
static inline u32 asr_r(CwCpu *c, u32 v, u32 s) {
    s &= 0xFF; if (!s) return nz(c, v);
    if (s < 32) { c->c = (v >> (s - 1)) & 1; return nz(c, (u32)((s32)v >> s)); }
    c->c = v >> 31; return nz(c, (u32)((s32)v >> 31));
}
static inline u32 ror_r(CwCpu *c, u32 v, u32 s) {
    s &= 0xFF; if (!s) return nz(c, v);
    if (!(s & 31)) { c->c = v >> 31; return nz(c, v); }
    v = ror32(v, s & 31); c->c = v >> 31; return nz(c, v);
}

/* ---- control flow -------------------------------------------------------------------- */
/* Loop guard on backward branches and computed jumps: lets tests stop code that would wait
 * forever for hardware (VBlank, DMA). The platform layer will run hardware events here. */
extern u64 cw_loop_limit;
#define CW_LOOP(c) do { if (++(c)->insns > cw_loop_limit) { if (!(c)->fault) { (c)->fault = 2; } (c)->ret = 0xFFFFFFFFu; return; } } while (0)

/* Calls the recompiled code at `target` (Thumb if bit 0, ARM otherwise). On return,
 * c->ret holds the address control went back to. */
void cw_call(CwCpu *c, u32 target);
void cw_swi(CwCpu *c, u32 num);
void cw_undefined(CwCpu *c, u32 addr, u32 insn);

typedef void (*CwFunc)(CwCpu *c, u32 entry);
typedef struct { u32 addr; CwFunc fn; } CwEntry;
extern const CwEntry cw_entries[];
extern const u32 cw_entry_count;

#endif
